-- DM metadata database: preserve existing menu IDs and role assignments.
-- This script can be run once after the new frontend has been deployed.
UPDATE JDDBMS.SYS_MENU SET MENU_NAME='用户与权限', PATH='access', ICON='user' WHERE MENU_ID=1;
UPDATE JDDBMS.SYS_MENU SET MENU_NAME='审计与运行', PATH='operations', ICON='monitor' WHERE MENU_ID=2;
UPDATE JDDBMS.SYS_MENU SET MENU_NAME='数据源控制', PATH='data-source-control', ICON='database' WHERE MENU_ID=3;
UPDATE JDDBMS.SYS_MENU SET MENU_NAME='平台用户' WHERE MENU_ID=100;
UPDATE JDDBMS.SYS_MENU SET MENU_NAME='平台角色' WHERE MENU_ID=101;
UPDATE JDDBMS.SYS_MENU SET VISIBLE='1' WHERE MENU_ID=4;
UPDATE JDDBMS.SYS_MENU SET PARENT_ID=2 WHERE MENU_ID=108;
UPDATE JDDBMS.SYS_MENU SET PARENT_ID=2000, VISIBLE='1' WHERE MENU_ID IN (102,103,104,105,107,115,116,117);
UPDATE JDDBMS.SYS_MENU SET PARENT_ID=2000, MENU_NAME='系统参数', VISIBLE='0' WHERE MENU_ID=106;
UPDATE JDDBMS.SYS_MENU SET VISIBLE='0' WHERE MENU_ID=102;
UPDATE JDDBMS.SYS_MENU SET VISIBLE='1' WHERE MENU_ID IN (110,111,112,113,114);

