 SELECT 2102,'修改数据',2001,3,'',NULL,1,0,'F','0','0','dbms:data:write','#','admin',CURRENT_TIMESTAMP FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM JDDBMS.SYS_MENU WHERE MENU_ID=2102);
 SELECT 2103,'修改结构与数据库用户',2001,4,'',NULL,1,0,'F','0','0','dbms:schema:change','#','admin',CURRENT_TIMESTAMP FROM DUAL
