 SELECT 10,'数据库开发人员','dbms_developer',10,'5',1,1,'0','0','admin',CURRENT_TIMESTAMP,'工作区与授权数据源的数据库操作' FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM JDDBMS.SYS_ROLE WHERE ROLE_ID=10);
 SELECT 11,'数据分析人员','dbms_reader',11,'5',1,1,'0','0','admin',CURRENT_TIMESTAMP,'仅查看授权数据源的结构和数据' FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM JDDBMS.SYS_ROLE WHERE ROLE_ID=11);
 SELECT 12,'数据源管理员','dbms_datasource',12,'5',1,1,'0','0','admin',CURRENT_TIMESTAMP,'管理本人负责的连接及授权' FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM JDDBMS.SYS_ROLE WHERE ROLE_ID=12);
 SELECT 13,'审计员','dbms_auditor',13,'5',1,1,'0','0','admin',CURRENT_TIMESTAMP,'查看授权范围内的运行和操作记录' FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM JDDBMS.SYS_ROLE WHERE ROLE_ID=13);
 SELECT 14,'安全管理员','dbms_security',14,'1',1,1,'0','0','admin',CURRENT_TIMESTAMP,'管理平台用户、角色及授权，不直接操作数据库' FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM JDDBMS.SYS_ROLE WHERE ROLE_ID=14);

 SELECT r.ROLE_ID,m.MENU_ID FROM JDDBMS.SYS_ROLE r JOIN JDDBMS.SYS_MENU m
 ON ((r.ROLE_ID IN (10,11,12) AND m.MENU_ID IN (3,2001))
  OR (r.ROLE_ID IN (10,11,13) AND m.MENU_ID IN (2,2002))
  OR (r.ROLE_ID=10 AND m.MENU_ID BETWEEN 2100 AND 2107)
  OR (r.ROLE_ID=11 AND m.MENU_ID IN (2100,2101,2105))
  OR (r.ROLE_ID=12 AND m.MENU_ID IN (2100,2107))
  OR (r.ROLE_ID=13 AND m.MENU_ID IN (2100,2105))
  OR (r.ROLE_ID=14 AND m.MENU_ID IN (2100,2107))
  OR (r.ROLE_ID=13 AND m.MENU_ID IN (108,500,501))
  OR (r.ROLE_ID=14 AND (m.MENU_ID IN (1,100,101,2,108,500,501,3,2001)
      OR m.PARENT_ID IN (100,101))))
 WHERE r.ROLE_ID IN (10,11,12,13,14)
 AND NOT EXISTS (SELECT 1 FROM JDDBMS.SYS_ROLE_MENU rm
                 WHERE rm.ROLE_ID=r.ROLE_ID AND rm.MENU_ID=m.MENU_ID);

-- Move existing ordinary users to the explicit developer template.
 SELECT old.USER_ID,10 FROM JDDBMS.SYS_USER_ROLE old
 WHERE old.ROLE_ID=2 AND NOT EXISTS
 (SELECT 1 FROM JDDBMS.SYS_USER_ROLE current_user_role WHERE current_user_role.USER_ID=old.USER_ID AND current_user_role.ROLE_ID=10);
DELETE FROM JDDBMS.SYS_USER_ROLE WHERE ROLE_ID=2;
DELETE FROM JDDBMS.SYS_ROLE_MENU WHERE ROLE_ID=2;
DELETE FROM JDDBMS.SYS_ROLE WHERE ROLE_ID=2
 AND NOT EXISTS (SELECT 1 FROM JDDBMS.SYS_USER_ROLE WHERE ROLE_ID=2);
COMMIT;

